 {view==='fleet'&&<><div className="section-heading"><h2>Hosts</h2></div><div className="host-grid"><HostCard name="Proxmox" ip="192.168.0.3" host={p}/><HostCard name="Unraid" ip="192.168.0.4" host={u} icon="layers"/><PiCard pi={fleet?.pi} observedAt={fleet?.observed_at}/></div><div className="section-heading"><h2>Compute fleet <span className="count">{filteredHosts.length} / {hostList.length}</span></h2><label className="inline-search"><Icon name="search" size={16}/><input aria-label="Filter hosts and containers" placeholder="Find a host…" value={search} onChange={ev=>setSearch(ev.target.value)}/></label></div><div className="fleet-table">{!filteredHosts.length&&<div className="empty"><h3>No matching hosts or containers</h3><button className="secondary-button" onClick={()=>setSearch('')}>Clear search</button></div>}<div className="fleet-row table-head"><span>NAME</span><span>PLATFORM</span><span>CPU</span><span>MEMORY</span><span>STATE</span></div>{filteredHosts.map(h=><div className="fleet-row" key={h.id}><span className="fleet-name"><span className="icon-tile"><Icon name={h.kind==='Docker'?'layers':'server'} size={17}/></span><strong>{h.name}<small>{h.detail}</small></strong></span><span>{h.kind}</span><span className="mono">{num(h.cpu,1)}%</span><span className="mono">{num(h.ram)} MiB</span><Badge state={h.online===false?null:h.online} label={h.online===true?'Running':h.online===false?'Stopped':'Unknown'}/></div>)}</div></>}
 {(view==='network'&&(!search||(data.ip_matrix||[]).some(h=>`${h.name} ${h.ip}`.toLowerCase().includes(search.toLowerCase()))))&&<><div className="section-heading"><h2>Network map</h2><span className="mono muted">192.168.0.0/24</span></div><div className="network-map">{(data.ip_matrix||[]).filter(h=>`${h.name} ${h.ip}`.toLowerCase().includes(search.toLowerCase())).map(h=><a href={h.url} key={h.ip} target="_blank" rel="noreferrer"><span className="ip-square">{h.octet}</span><div><strong>{h.name}</strong><small>{h.role}</small></div><i className={h.online?'tiny-dot':'tiny-dot unknown'}/></a>)}</div></>}
